    payment_provider, provider_transaction_id, created_at, paid_at
) VALUES (
    #{id}, #{payment.tenantId}, #{payment.userId}, #{payment.planCode}, #{payment.planName},
    #{payment.amountMinor}, #{payment.currency}, #{payment.paymentProvider},
    #{payment.providerTransactionId}, CURRENT_TIMESTAMP, #{payment.paidAt}
) ON CONFLICT (payment_provider, provider_transaction_id) DO NOTHING

mapper.select:
SELECT id, tenant_id, user_id, plan_code, plan_name, amount_minor, currency,
       payment_provider, provider_transaction_id, paid_at
  FROM recharge_record
 WHERE payment_provider = #{paymentProvider}
   AND provider_transaction_id = #{providerTransactionId}
